import test from 'node:test';
import assert from 'node:assert/strict';
import { sessions } from './solution.mjs';

const run = records => sessions({ gap_ms: 10, lateness_ms: 0, records });

test('a bridge creates one session and retracting it splits sessions', () => {
  const base = [
    {kind:'upsert',id:'a',rev:1,key:'k',event_time:0,amount:2},
    {kind:'upsert',id:'c',rev:1,key:'k',event_time:20,amount:4},
    {kind:'upsert',id:'b',rev:1,key:'k',event_time:10,amount:3},
  ];
  assert.deepEqual(run(base).sessions, [{key:'k',start:0,end:30,total:9,count:3,ids:['a','b','c'],final:false}]);
  assert.deepEqual(run([...base,{kind:'delete',id:'b',rev:2}]).sessions, [
    {key:'k',start:0,end:10,total:2,count:1,ids:['a'],final:false},
    {key:'k',start:20,end:30,total:4,count:1,ids:['c'],final:false},
  ]);
});

test('retraction can split and finalize only the older result', () => {
  const r = sessions({gap_ms:10,lateness_ms:0,records:[
    {kind:'upsert',id:'a',rev:1,key:'k',event_time:0,amount:1},
    {kind:'upsert',id:'b',rev:1,key:'k',event_time:10,amount:1},
    {kind:'upsert',id:'c',rev:1,key:'k',event_time:20,amount:1},
    {kind:'watermark',time:25}, // merged end 30 remains open
    {kind:'delete',id:'b',rev:2}, // [a] has end 10 and seals
  ]});
  assert.deepEqual(r.sessions,[
    {key:'k',start:0,end:10,total:1,count:1,ids:['a'],final:true},
    {key:'k',start:20,end:30,total:1,count:1,ids:['c'],final:false},
  ]);
  assert.throws(() => sessions({gap_ms:10,lateness_ms:0,records:[...r.records]}));
});

test('sealed events reject changes, while accepted replay and old revision do nothing', () => {
  const prefix=[{kind:'upsert',id:'a',rev:2,key:'x',event_time:0,amount:0},{kind:'watermark',time:10}];
  assert.throws(() => run([...prefix,{kind:'delete',id:'a',rev:3}]));
  assert.deepEqual(run([...prefix,{kind:'upsert',id:'a',rev:2,key:'x',event_time:0,amount:0},{kind:'upsert',id:'a',rev:1,key:'z',event_time:4,amount:9}]).sessions,
    [{key:'x',start:0,end:10,total:0,count:1,ids:['a'],final:true}]);
  assert.throws(() => run([...prefix,{kind:'upsert',id:'a',rev:2,key:'x',event_time:1,amount:0}]));
});

test('proposal uses session connectivity rather than fixed windows and can save an old event', () => {
  const out=sessions({gap_ms:10,lateness_ms:0,records:[
    {kind:'upsert',id:'new',rev:1,key:'k',event_time:100,amount:1},
    {kind:'watermark',time:105},
    {kind:'upsert',id:'old',rev:1,key:'k',event_time:90,amount:2},
  ]});
  assert.deepEqual(out.sessions,[{key:'k',start:90,end:110,total:3,count:2,ids:['new','old'],final:false}]);
});

test('unknown delete is a revision tombstone and sealed proximity is rejected atomically', () => {
  const p=[{kind:'delete',id:'gone',rev:4},{kind:'upsert',id:'s',rev:1,key:'k',event_time:0,amount:1},{kind:'watermark',time:10}];
  const x=sessions({gap_ms:10,lateness_ms:0,records:[...p,{kind:'upsert',id:'gone',rev:3,key:'k',event_time:100,amount:1}]});
  assert.equal(x.sessions.length,1);
  assert.throws(() => sessions({gap_ms:10,lateness_ms:0,records:[...p,{kind:'upsert',id:'n',rev:1,key:'k',event_time:20,amount:1}]));
});

